78	    // Gather all ReduceCost effects from permanents the caster controls.
79	    let mut total_reduction: u32 = 0;
80	    for obj in state.objects.values() {
81	        if obj.zone != Zone::Battlefield || obj.controller != caster {
82	            continue;
83	        }
84	        if let Some(behavior) = registry.get(obj.card_id) {
85	            for effect in &behavior.card_data().continuous_effects {
86	                if let ContinuousEffect::ReduceCost { reduction, filter } = effect {
87	                    let applies = match filter {
88	                        SpellFilter::CreatureSpells => is_creature,
89	                        SpellFilter::CreatureWithSubtype(sub) => {
90	                            is_creature && subtypes.iter().any(|s| s == sub)
91	                        }
92	                    };
93	                    if applies {
